proj/.claude/settings.json:
{
  "$schema": "https://json.schemastore.org/claude-code-settings.json",
  "permissions": {
    "allow": [
      "Bash(awf build:*)",
      "Bash(awf check-envelope:*)",
      "Bash(awf check-rules:*)",
      "Bash(awf check-agents:*)",
      "Bash(awf save-run:*)",
      "Bash(git status:*)",
      "Bash(git diff:*)",
      "Bash(git log:*)"
    ],
    "deny": [
      "Read(./.env)",
      "Read(./.env.*)",
      "Read(**/.env)",
      "Read(**/.env.*)",
      "Read(**/*.pem)",
      "Read(**/*.key)"
    ]
  },
  "hooks": {
    "PreToolUse": [
      {"matcher": "Bash|PowerShell", "hooks": [{"type": "command", "command": "\"@TMP@/proj/.claude/hooks/bin/awf\" hook guard-shell", "timeout": 10, "onFailure": "block"}]},
      {"matcher": "Edit|Write|NotebookEdit|Read|Grep", "hooks": [{"type": "command", "command": "\"@TMP@/proj/.claude/hooks/bin/awf\" hook guard-paths", "timeout": 10, "onFailure": "block"}]},
      {"matcher": "SubagentHandback|StructuredOutput", "hooks": [{"type": "command", "command": "\"@TMP@/proj/.claude/hooks/bin/awf\" hook envelope", "onFailure": "continue"}]}
    ],
    "SubagentStop": [
      {"hooks": [{"type": "command", "command": "\"@TMP@/proj/.claude/hooks/bin/awf\" hook envelope"}]}
    ],
    "TaskCompleted": [
      {"hooks": [{"type": "command", "command": "\"@TMP@/proj/.claude/hooks/bin/awf\" hook envelope"}]}
    ]
  }
}

