  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "python3 \"${CLAUDE_PROJECT_DIR}/.claude/hooks/awf_hook.py\" guard-shell"
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "echo mine"
          },
          {
            "type": "command",
            "command": "\"/old/python\" \"x/awf_hook.py\" guard-paths",
            "timeout": 3
          }
        ]
      },
      {
        "matcher": "Other",
        "hooks": []
      },
      {
        "matcher": "Keep",
        "hooks": [
          {
            "type": "command",
            "command": "awf_hook.py unknown-mode"
          },
          {
            "type": "command",
            "command": "awf_hook.pyc envelope"
          }
        ]
      },
      "不是物件的項目",
      {
        "matcher": "NoHooks"
      }
    ],
    "SubagentStop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "py awf_hook.py   envelope"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "py awf_hook.py envelope"
          }
        ]
      }
    ]
  }
}

